<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>(()=>{const button=document.getElementById('customerThemeToggle');if(!button)return;const applyTheme=dark=>{document.body.classList.toggle('dark-mode',dark);button.innerHTML=dark?'&#9788;':'&#9790;';button.setAttribute('aria-label',dark?'Enable light mode':'Enable dark mode');button.setAttribute('title',dark?'Enable light mode':'Enable dark mode');button.setAttribute('aria-pressed',String(dark))};applyTheme(localStorage.getItem('customer-theme')==='dark');button.addEventListener('click',()=>{const dark=!document.body.classList.contains('dark-mode');localStorage.setItem('customer-theme',dark?'dark':'light');applyTheme(dark)})})();</script></body></html>
